(()=>{const input=document.getElementById('smartSearch');if(!input)return;const panel=document.getElementById('smartSuggest'),url=input.dataset.suggestUrl,form=input.form;let timer,ctrl,items=[],active=-1,last='';const cache=new Map();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mark=(text,q)=>{let out=esc(text);q.toLowerCase().match(/[\p{L}\p{N}]+/gu)?.forEach(t=>{if(t.length<2)return;out=out.replace(new RegExp('('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'),'<mark>$1</mark>')});return out};
const close=()=>{panel.hidden=true;input.setAttribute('aria-expanded','false');active=-1};
const setActive=i=>{const els=panel.querySelectorAll('.ss-item,.ss-all');els.forEach(e=>e.classList.remove('is-active'));active=i;if(els[i]){els[i].classList.add('is-active');els[i].scrollIntoView({block:'nearest'});input.setAttribute('aria-activedescendant',els[i].id)}};
const render=(q,results)=>{items=results;if(!results.length){panel.innerHTML='<div class="ss-empty">No quick matches for “'+esc(q)+'”. Press Search to look everywhere.</div>'}else{panel.innerHTML=results.map((r,i)=>'<a class="ss-item" role="option" id="ss-'+i+'" href="'+esc(r.url)+'"><span class="ss-logo">'+(r.logo?'<img src="'+esc(r.logo)+'" alt="" loading="lazy">':esc(r.initials))+'</span><span class="ss-text"><span class="ss-name">'+mark(r.name,q)+'</span><span class="ss-meta">'+mark(r.match||r.category||'Business',q)+'</span></span>'+(r.sponsored?'<span class="ss-badge">Sponsored</span>':'')+'</a>').join('')+'<a class="ss-all" role="option" id="ss-all" href="#">See all results for “'+esc(q)+'”</a>';panel.querySelector('.ss-all').addEventListener('click',e=>{e.preventDefault();form.submit()})}panel.hidden=false;input.setAttribute('aria-expanded','true');active=-1};
const run=()=>{const q=input.value.trim();if(q.length<2){close();return}if(q===last&&!panel.hidden)return;last=q;if(cache.has(q)){render(q,cache.get(q));return}ctrl?.abort();ctrl=new AbortController();
fetch(url+'?q='+encodeURIComponent(q),{headers:{'Accept':'application/json'},signal:ctrl.signal}).then(r=>r.ok?r.json():{results:[]}).then(d=>{cache.set(q,d.results||[]);if(input.value.trim()===q)render(q,d.results||[])}).catch(()=>{})};
input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(run,220)});
input.addEventListener('focus',()=>{if(input.value.trim().length>=2){last='';run()}});
input.addEventListener('keydown',e=>{if(panel.hidden)return;const n=panel.querySelectorAll('.ss-item,.ss-all').length;if(e.key==='ArrowDown'){e.preventDefault();setActive((active+1)%n)}else if(e.key==='ArrowUp'){e.preventDefault();setActive((active-1+n)%n)}else if(e.key==='Enter'&&active>=0){e.preventDefault();panel.querySelectorAll('.ss-item,.ss-all')[active].click()}else if(e.key==='Escape'){close()}});
document.addEventListener('click',e=>{if(!e.target.closest('.smart-search'))close()});})();
</script></body></html>
